extractor:
function extract(raw, memory, info) {
  info = info || {};
  if (!raw || typeof raw !== 'object' || !Array.isArray(raw.road) || typeof raw.playerX !== 'number') {
    memory.x = null; memory.s = null; memory.t = null; memory.cars = {}; memory.target = null;
    return { ready: false };
  }
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function r2(v) { return Math.round(v * 100) / 100; }
  var i, j, k;
  var lag = clamp((+info.lagMs || 0) / 1000, 0, 0.5);
  var DT = 0.016, TK = 6, TICK = DT * TK, NSTEP = 125, HM = 0.03, SOFT = 0.12;
  var seg = +raw.segmentLength || 200;
  var MAXV = seg * 60;
  var cf = typeof raw.centrifugal === 'number' ? raw.centrifugal : 0.3;
  var pw = +raw.playerW || 0.3;
  var s0 = clamp(+raw.speed || 0, 0, 1);
  var x0 = raw.playerX;
  var road = raw.road, RL = road.length;
  function cv(q) { if (!RL) return 0; var r = road[q < 0 ? 0 : (q < RL ? q : RL - 1)]; return r ? (+r.curve || 0) : 0; }
  var now = typeof info.nowMs === 'number' ? info.nowMs : (typeof memory.t === 'number' ? memory.t + 96 : 0);
  var dt = typeof memory.t === 'number' ? (now - memory.t) / 1000 : 0;
  if (!(dt > 0.005 && dt < 0.5)) dt = 0;
  var vx = -2 * cf * s0 * s0 * cv(0), sv = 0;
  if (dt && typeof memory.x === 'number') {
    var lim = 2 * s0 + Math.abs(vx) + 0.05;
    vx = clamp((x0 - memory.x) / dt, -lim, lim);
  }
  if (dt && typeof memory.s === 'number') sv = clamp((s0 - memory.s) / dt, -1.2, 0.2);
  memory.x = x0; memory.s = s0; memory.t = now;
  var xL = x0 + vx * lag, sL = clamp(s0 + sv * lag, 0, 1);
  var pz0 = (s0 + sL) / 2 * MAXV * lag;
  var side = Array.isArray(raw.side) ? raw.side : [], frac = null;
  for (i = 0; i < side.length; i++) {
    var sd = side[i];
    if (!sd || typeof sd !== 'object' || typeof sd.dz !== 'number') continue;
    var f = ((-sd.dz) % seg + seg) % seg;
    if (frac === null) frac = f;
    else if (Math.min(Math.abs(f - frac), seg - Math.abs(f - frac)) > 4) { frac = null; break; }
  }
  var fr = frac === null ? seg / 2 : frac, ZM = frac === null ? seg / 2 : 30;
  var sprites = [];
  for (i = 0; i < side.length; i++) {
    var so = side[i];
    if (!so || typeof so !== 'object') continue;
    var off = +so.offset || 0, sw = +so.w || 0.5;
    sprites.push({ k: Math.round(((+so.dz || 0) + fr) / seg), ctr: off + (off > 0 ? 1 : -1) * sw / 2, half: (pw + sw) / 2 });
  }
  var T = lag + NSTEP * DT, prev = memory.cars || {}, seen = {}, cars = [];
  var list = Array.isArray(raw.cars) ? raw.cars : [];
  for (i = 0; i < list.length; i++) {
    var c = list[i];
    if (!c || typeof c !== 'object') continue;
    var o = +c.offset || 0, w = +c.w || 0.3, cs = +c.speed || 0, dz = +c.dz || 0;
    var key = w.toFixed(3) + '|' + cs.toFixed(3);
    var cvx = 0;
    if (dt && typeof prev[key] === 'number' && Math.abs(o - prev[key]) < 0.5) cvx = clamp((o - prev[key]) / dt, -1.5, 1.5);
    seen[key] = o;
    if (cs >= 1 || dz < -2 * seg || dz + (cs - 1) * MAXV * T > seg + ZM) continue;
    var lo = [], hi = [], cx = [];
    for (k = 0; k < NSTEP; k++) {
      var ct = lag + (k + 1) * DT, cz = fr + dz + cs * MAXV * ct;
      lo.push(Math.floor((cz - ZM) / seg)); hi.push(Math.floor((cz + ZM) / seg));
      cx.push(o + cvx * Math.min(ct, 0.3));
    }
    cars.push({ cs: cs, dz: dz, half: 0.4 * (pw + w), lo: lo, hi: hi, cx: cx });
  }
  memory.cars = seen;
  var n = cars.length;
  function sim(xt, b0, b1) {
    var x = xL, sp = sL, pz = pz0, pen = 0, off = false, hitT = 0, steer = 0, g = [], a, m, t;
    for (a = 0; a < n; a++) g.push(9);
    for (t = 0; t < NSTEP; t++) {
      var idx = Math.floor((fr + pz) / seg), cu = cv(idx);
      if (t % TK === 0) {
        var st = 2 * sp * TICK, d = xt - (x - 2 * cf * sp * sp * cu * TICK);
        steer = d > st / 2 ? 1 : (d < -st / 2 ? -1 : 0);
      }
      var dx = 2 * sp * DT;
      pz += sp * MAXV * DT;
      x += steer * dx - dx * sp * cu * cf;
      sp += (t >= b0 && t < b1) ? -DT : 0.2 * DT;
      if (x < -1 || x > 1) {
        if (sp > 0.25) sp -= 0.5 * DT;
        pen += 0.5 * DT;
        if (!off) { off = true; pen += 0.5; }
        for (m = 0; m < sprites.length; m++) {
          var p = sprites[m];
          if (p.k === idx && Math.abs(x - p.ctr) <= p.half) { sp = 0.2; pz = idx * seg - fr; break; }
        }
      }
      if (sp < 0) sp = 0; else if (sp > 1) sp = 1;
      for (a = 0; a < n; a++) {
        var cr = cars[a];
        if (sp <= cr.cs || idx < cr.lo[t] || idx > cr.hi[t]) continue;
        var gap = Math.abs(x - cr.cx[t]) - cr.half;
        if (gap < HM) {
          sp = cr.cs * cr.cs / sp;
          pz = cr.dz + cr.cs * MAXV * (lag + (t + 1) * DT);
          if (!hitT) hitT = (t + 1) * DT;
          break;
        }
        if (gap < g[a]) g[a] = gap;
      }
    }
    var v = pz / MAXV - 2.5 * (1 - sp) * (1 - sp) - pen;
    for (a = 0; a < n; a++) if (g[a] < SOFT) v -= 0.12 * (SOFT - g[a]);
    return { v: v, hit: hitT };
  }
  var fz = pz0, fs = sL;
  for (k = 0; k < NSTEP; k++) { fz += fs * MAXV * DT; fs = Math.min(1, fs + 0.2 * DT); }
  var vFree = fz / MAXV - 2.5 * (1 - fs) * (1 - fs);
  var cMax = 0;
  for (i = 0; i < RL; i++) { var cc = cv(i); if (Math.abs(cc) > Math.abs(cMax) + 1e-9) cMax = cc; }
  var xPref = (cMax > 0 ? 1 : -1) * clamp((Math.abs(cMax) - 1) * 0.2, 0, 0.6);
  var cands = [clamp(xL, -0.8, 0.8)];
  for (i = -5; i <= 5; i++) cands.push(i * 0.16);
  var sch = [[TK, TK], [TK, 2 * TK], [TK, 3 * TK], [TK, 5 * TK], [TK, 9 * TK], [0, TK], [0, 2 * TK], [0, 4 * TK], [0, 8 * TK]];
  var pt = memory.target, bestK = null, bestS = null, lineHit = 0;
  for (i = 0; i < cands.length; i++) {
    var xc = cands[i];
    var tie = 0.02 * Math.abs(xc - xL) + 0.03 * Math.abs(xc - xPref) - (typeof pt === 'number' && Math.abs(xc - pt) < 0.09 ? 0.01 : 0);
    for (j = 0; j < sch.length; j++) {
      var res = sim(xc, sch[j][0], sch[j][1]), sc = res.v - tie;
      if (i === 0 && j === 0) lineHit = res.hit;
      if (sch[j][0] > 0) { if (!bestK || sc > bestK.sc + 1e-9) bestK = { sc: sc, x: xc }; }
      else if (!bestS || sc > bestS.sc + 1e-9) bestS = { sc: sc, x: xc };
    }
  }
  var keepLoss = (vFree - bestK.sc) * 60, gain = (bestS.sc - bestK.sc) * 60;
  var slow = gain >= 0.5, best = slow ? bestS : bestK;
  memory.target = best.x;
  var sg = Math.round(gain * 10) / 10;
  if (slow && sg < 0.5) sg = 0.5;
  if (!slow && sg >= 0.5) sg = 0.4;
  var cL = cv(Math.floor((fr + pz0) / seg));
  var xNo = xL - 2 * cf * sL * sL * cL * TICK;
  var dxs = clamp((best.x - xNo) / (2 * Math.max(sL, 0.05) * TICK), -9.9, 9.9);
  return {
    ready: true,
    speed: r2(sL),
    x: r2(xL),
    offRoad: Math.abs(xL) > 1,
    curve: Math.round(cL * 10) / 10,
    openX: r2(best.x),
    openDxSteps: Math.round(dxs * 10) / 10,
    keepLoss: Math.round(clamp(keepLoss, 0, 999)),
    slowGain: clamp(sg, -9.9, 99),
    lineHitMs: lineHit ? Math.round(lineHit * 1000) : 2000
  };
}

teacher:
function teach(state) {
  if (!state || !state.ready) return 'gas';
  var side = state.openDxSteps >= 0.5 ? 'Right' : (state.openDxSteps <= -0.5 ? 'Left' : '');
  return (state.slowGain >= 0.5 ? 'brake' : 'gas') + side;
}
